1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo } from "./promotions";
14	import {
15	  claimFirstMonthFree,
16	  firstMonthFreeEnabled,
17	  firstMonthFreeAppliesTo,
18	  setPromoOrderRef,
19	} from "./promo-redemption";
20	import { extraDiskPerGbCents } from "./disk-expand";
21	import {
22	  EXTRA_DISK_MAX_ADD_GB,
23	  EXTRA_DISK_MAX_TOTAL_GB,
24	  effectiveDiskGB,
25	  extraDiskCentsAt,
26	  extraDiskLabel,
27	  normalizeExtraDiskGB,
28	} from "./extra-disk";
29	import { getSettingBool } from "./settings";
30	import { couponOrderDiscountCents } from "./coupon-order";
31	
32	export class OrderError extends Error {}
33	
34	export const orderSchema = z.object({
35	  planId: z.string().min(1),
36	  osTemplateId: z.string().min(1),
37	  hostname: z
38	    .string()
39	    .min(3)
40	    .max(40)
41	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
42	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
43	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
44	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
45	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
46	  // redemption guards live in orderQuote / placeOrder.
47	  couponCode: z.string().trim().max(32).optional(),
48	});
49	
50	export type OrderIntent = {
51	  planId: string;
52	  osTemplateId: string;
53	  hostname: string;
54	  nodeId?: string;
55	  addonMalware?: boolean;
56	  addonBackup?: boolean;
57	  addonDocker?: boolean;
58	  termMonths?: number;
59	  dedicatedIp?: boolean;
60	  sshPublicKey?: string;
61	  sshKeyName?: string;
62	  free?: boolean;
63	  /**
64	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
65	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
66	   * post-deploy expansion job is needed. Permanent — never shrinks.
67	   */
68	  extraDiskGB?: number;
69	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
70	  couponCode?: string;
71	};
72	
73	/**
74	 * The price an order was SOLD at: the total, and the promo rate that produced it.
75	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
76	 *
77	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
78	 * path quoted a total, charged the CARD its share of that total at Stripe, and
79	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
80	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
81	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
82	 * so a rotation between "customer clicked Deploy" and "customer came back from
83	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
84	 * out of the wallet with no new consent. With no balance to take it from, the
85	 * payment was captured and no server was created.
86	 *
87	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
88	 * Stripe metadata for exactly this reason; the order path was the one that
89	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
90	 * the customer was shown is not recomputed later, it is carried.
91	 *
92	 * `promoPercent` and `promoName` travel WITH the total because they are not
93	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
94	 * at (every later proration prices against it), and the promo name is the ledger
95	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
96	 * today's 15% would hand every later proration the wrong basis and print a
97	 * discount on the invoice that does not match the money taken.
98	 */
99	export type OrderPrice = {
100	  /** Total to charge, in cents — the figure the customer consented to. */
101	  chargeCents: number;
102	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
103	  promoPercent: number;
104	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
105	  promoName: string;
106	};
107	
108	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
109	export function orderPriceOf(quote: {
110	  chargeCents: number;
111	  promo: { discountPercent: number; name: string };
112	}): OrderPrice {
113	  return {
114	    chargeCents: quote.chargeCents,
115	    promoPercent: quote.promo.discountPercent,
116	    promoName: quote.promo.name,
117	  };
118	}
119	
120	/**
121	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
122	 * well-formed: a half-parsed price would be worse than no price at all, because
123	 * the caller's fallback (re-quote) is at least internally consistent.
124	 */
125	export function parseOrderPrice(raw: unknown): OrderPrice | null {
126	  let obj: unknown = raw;
127	  if (typeof raw === "string") {
128	    try {
129	      obj = JSON.parse(raw);
130	    } catch {
131	      return null;
132	    }
133	  }
134	  if (!obj || typeof obj !== "object") return null;
135	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
136	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
137	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
138	  if (promoPercent < 0 || promoPercent > 100) return null;
139	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
140	}
141	
142	/** Extract a plain OrderIntent from a deploy form. */
143	export function intentFromFormData(formData: FormData): OrderIntent {
144	  return {
145	    planId: String(formData.get("planId") ?? ""),
146	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
147	    hostname: String(formData.get("hostname") ?? ""),
148	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
149	    addonMalware: formData.get("addon_malware") === "1",
150	    addonBackup: formData.get("addon_backup") === "1",
151	    addonDocker: formData.get("addon_docker") === "1",
152	    termMonths: Number(formData.get("termMonths") ?? 1),
153	    dedicatedIp: formData.get("dedicatedIp") === "1",
154	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
155	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
156	    free: formData.get("free") === "1",
157	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
158	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
159	    // bought so it drops out of JSON.stringify: the intent is round-tripped
160	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
161	    // createOrderCheckout), and every byte of headroom matters there.
162	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
163	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
164	  };
165	}
