167	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
168	async function scheduleNode(planRamMB: number) {
169	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
170	  if (nodes.length === 0) return null;
171	  const loads = await Promise.all(
172	    nodes.map(async (n) => {
173	      const agg = await db.server.findMany({
174	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
175	        select: { plan: { select: { ramMB: true } } },
176	      });
177	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
178	      return { node: n, free: n.capacityRamMB - used };
179	    }),
180	  );
181	  loads.sort((a, b) => b.free - a.free);
182	  return loads[0].node;
183	}
184	
185	/** Validate + price an order without placing it. Throws OrderError on any problem. */
186	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
187	  const parsed = orderSchema.safeParse(intent);
188	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
189	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
190	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
191	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
192	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
193	    throw new OrderError(
194	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
195	    );
196	  }
197	  const term = vpsTerm(Number(intent.termMonths ?? 1));
198	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
199	
200	  // Extra root disk, priced per GB/month and multiplied over the term exactly
201	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
202	  // promo — the customer pays the same $/GB whichever term they pick, and renews
203	  // at the same rate). Growth is one-way: this is permanent for the server.
204	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
205	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
206	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
207	  const extraDiskCents = extraDiskMonthlyCents * term.months;
208	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
209	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
210	  }
211	
212	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
213	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
214	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
215	  // real renewal price and this discounted value is the real first-term price.
216	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
217	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
218	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
219	  const promo = currentPromo(new Date());
220	  // The promo is now MANAGED: the owner can switch it off, and every claim is
221	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
222	  // quote shows — and placeOrder charges — the full price, so display === charged
223	  // on the disabled path. When it is on, the quote shows the first-month-free
224	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
225	  // the credit is actually granted (a lost race there is charged full).
226	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
227	  // the card path uses it to re-quote for a customer who has already redeemed
228	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
229	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
230	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
231	  // false here and planFirstTermCents falls through to the regular term total.
232	  const promoEnabled =
233	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
234	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
235	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
236	  // YEARS free. So we subtract one month of the plan's rate from the term total.
237	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
238	  // 36-month term the customer pays the term minus one month. Renewals bill the
239	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
240	  const planFirstTermCents =
241	    promoEnabled && promo.firstMonthFree
242	      ? Math.max(0, regularPlanCents - plan.priceCents)
243	      : regularPlanCents;
244	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
245	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
246	  const promoCreditCents = regularPlanCents - planFirstTermCents;
247	
248	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
249	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
250	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
251	  // so the deploy preview can show it; the redemption itself (count + per-user +
252	  // per-IP guards) is claimed atomically in placeOrder.
253	  let couponId: string | null = null;
254	  let couponDiscountCents = 0;
255	  let couponLabel = "";
256	  let couponError = "";
257	  let couponMaxRedemptions: number | null = null;
258	  let couponFirstTimeOnly = false;
259	  const code = (intent.couponCode ?? "").trim().toUpperCase();
260	  if (code) {
261	    if (!(await getSettingBool("coupons_enabled", true))) {
262	      couponError = "Promo codes are currently disabled.";
263	    } else {
264	      const coupon = await db.coupon.findUnique({ where: { code } });
265	      if (!coupon) {
266	        couponError = "That code isn’t valid.";
267	      } else {
268	        const verdict = couponOrderDiscountCents(
269	          {
270	            kind: coupon.kind,
271	            value: coupon.value,
272	            serviceKind: coupon.serviceKind,
273	            planSlug: coupon.planSlug,
274	            maxTermMonths: coupon.maxTermMonths,
275	            active: coupon.active,
276	            expiresAt: coupon.expiresAt,
277	            maxRedemptions: coupon.maxRedemptions,
278	            timesRedeemed: coupon.timesRedeemed,
279	            minAmountCents: coupon.minAmountCents,
280	          },
281	          {
282	            serviceKind: "VPS",
283	            planSlug: plan.slug,
284	            planMonthlyCents: plan.priceCents,
285	            termMonths: term.months,
286	            planChargeCents: planFirstTermCents,
287	          },
288	          new Date(),
289	        );
290	        if (verdict.ok) {
291	          couponId = coupon.id;
292	          couponDiscountCents = verdict.discountCents;
293	          couponLabel = verdict.label;
294	          couponMaxRedemptions = coupon.maxRedemptions;
295	          couponFirstTimeOnly = coupon.firstTimeOnly;
296	        } else {
297	          couponError = verdict.error;
298	        }
299	      }
300	    }
301	  }
302	
303	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents;
304	  return {
305	    plan,
306	    os,
307	    term,
308	    chargeCents,
309	    promo,
310	    promoCreditCents,
311	    regularPlanCents,
312	    extraDiskGB,
313	    extraDiskMonthlyCents,
314	    extraDiskCents,
315	    couponId,
316	    couponDiscountCents,
317	    couponLabel,
318	    couponError,
319	    couponMaxRedemptions,
320	    couponFirstTimeOnly,
321	  };
322	}
323	
324	/**
325	 * Place an order: validate, charge the wallet (unless a free admin grant),
326	 * create the Server + PROVISION job. Returns the new server id. Does NOT
327	 * redirect. Callers must ensure funds exist (or pass free) — this still
328	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
329	 *
330	 * `sold` overrides the recomputed price with the one the order was actually SOLD
331	 * at — the card-paid path passes the figure stamped on the Checkout session
332	 * BEFORE the card was charged, so the confirm redirect settles the price the
333	 * customer consented to instead of re-pricing against whatever promo is running
334	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
335	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
336	 * quote, which it computed moments ago in the same request. See OrderPrice.
337	 */
338	/**
339	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
340	 * any failure so nothing partial survives. Kept separate from the order tx so a
341	 * wallet order can surface the failure before any money moves, and a card order
342	 * (already paid) can swallow it without stranding the paid provision.
343	 *
344	 * Guards, all enforced here: first-time-only (no prior paid server), the
345	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
346	 * (the two @@unique constraints on CouponRedemption).
347	 */
348	async function claimOrderCoupon(opts: {
349	  couponId: string;
350	  maxRedemptions: number | null;
351	  firstTimeOnly: boolean;
352	  userId: string;
353	  ipHash: string | null;
354	  amountCents: number;
355	}): Promise<void> {
356	  await db.$transaction(async (tx) => {
357	    if (opts.firstTimeOnly) {
358	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
359	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
360	    }
361	    // Atomic conditional increment — the only thing between the last free slot and
362	    // an over-redemption when two orders race for it.
363	    const claim = await tx.coupon.updateMany({
364	      where:
365	        opts.maxRedemptions === null
366	          ? { id: opts.couponId, active: true }
367	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
368	      data: { timesRedeemed: { increment: 1 } },
369	    });
370	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
371	    try {
372	      await tx.couponRedemption.create({
373	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
374	      });
375	    } catch {
376	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
377	      // this person. Throwing rolls back the increment above with it.
378	      throw new OrderError("You’ve already used this code.");
379	    }
380	  });
381	}
382	
383	/**
384	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
385	 *
386	 * The card leg discounts `cardCents` up front and only settles the redemption
387	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
388	 * paid provision is never stranded. Without this pre-check, a customer who has
389	 * already used a one-per-person code (or isn't first-time) still gets the
390	 * discounted card charge and the swallow hides it. So before we send them to
391	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
392	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
393	 * (a race could still lose the atomic claim at settle time — that path stays
394	 * swallowed by design), but it closes the everyday bypass.
395	 */
396	export async function orderCouponClaimable(opts: {
397	  couponId: string;
398	  firstTimeOnly: boolean;
399	  maxRedemptions: number | null;
400	  userId: string;
401	  ipHash: string | null;
402	}): Promise<{ ok: true } | { ok: false; error: string }> {
403	  if (opts.firstTimeOnly) {
404	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
405	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
406	  }
407	  const byUser = await db.couponRedemption.findUnique({
408	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
409	  });
410	  if (byUser) return { ok: false, error: "You’ve already used this code." };
411	  if (opts.ipHash) {
412	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
413	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
414	  }
415	  if (opts.maxRedemptions !== null) {
416	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
417	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
418	  }
419	  return { ok: true };
420	}
421	
422	export async function placeOrder(
423	  user: User,
424	  intent: OrderIntent,
425	  sold?: OrderPrice | null,
426	  opts?: { ipHash?: string | null; campaign?: string },
427	): Promise<string> {
428	  const quote = await orderQuote(intent);
429	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } = quote;
430	  // Everything below bills off THESE three, never off `quote.chargeCents` /
431	  // `promo` directly: when a sold price is present it is the whole truth about
432	  // what this order costs and what rate it was sold at.
433	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
434	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
435	  const promoName = sold?.promoName || promo.name;
436	  // Note the intro discount on the billing document (first term only; renews full).
437	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
438	
439	  // Managed first-month-free: is the price we're settling one that carries the
440	  // credit? Wallet path prices off the fresh quote (promoCreditCents), card path
441	  // off the sold rate. Only then do we contend for the atomic claim below.
442	  const promoApplied = sold ? sold.promoPercent > 0 : promoCreditCents > 0;
443	
444	  const cap = await capacityCheck(plan.id);
445	  if (!cap.ok) throw new OrderError(cap.reason);
446	
447	  let nodeId: string | null = null;
448	  if (intent.nodeId) {
449	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
450	    if (!n) throw new OrderError("Selected location is not available.");
451	    nodeId = n.id;
452	  } else {
453	    const n = await scheduleNode(plan.ramMB);
454	    nodeId = n?.id ?? null;
455	  }
456	
457	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
458	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
459	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
460	
461	  const addons = {
462	    malwareScanner: !!intent.addonMalware,
463	    dailyBackup: !!intent.addonBackup,
464	    docker: !!intent.addonDocker,
465	  };
466	  const isAdmin = user.role === "ADMIN";
467	  const freeRequested = !!intent.free && isAdmin;
468	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
469	
470	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
471	  // money moved) if the last slot just went. A free admin grant never consumes a
472	  // customer coupon. On the card-settle path the payment already cleared, so a
473	  // late claim failure must not strand the paid provision — log and continue.
474	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
475	    try {
476	      await claimOrderCoupon({
477	        couponId: quote.couponId,
478	        maxRedemptions: quote.couponMaxRedemptions,
479	        firstTimeOnly: quote.couponFirstTimeOnly,
480	        userId: user.id,
481	        ipHash: opts?.ipHash ?? null,
482	        amountCents: quote.couponDiscountCents,
483	      });
484	    } catch (e) {
