516	async function remove(job: Job) {
517	  const server = await loadServer(job);
518	  const { conn } = await nodeFor(server);
519	  if (!SANDBOX && server.vmid) {
520	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
521	    // so the absent case no longer needs to be caught here at all. The catch that
522	    // remains is narrowed to this vmid: it used to swallow any error containing
523	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
524	    // `volume ... does not exist` — errors that mean the VM is very much still
525	    // running. On one of those the handler proceeded to delete the Server row and
526	    // every Volume row pinned to it, leaving a live VM with no database record:
527	    // invisible to billing, invisible to the panel, still holding the customer's
528	    // data and impossible to reach through any surface we own.
529	    try {
530	      await destroyVm(conn, server.vmid);
531	    } catch (e: any) {
532	      if (!isVmAbsentError(e, server.vmid)) throw e;
533	    }
534	    // Best-effort: remove the per-server cloud-init snippet
535	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
536	  }
537	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
538	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
539	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
540	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
541	  // diskName and keep billing forever. Remove them and notify the owner. (The
542	  // reinstall guard already blocks the accidental case; a full server delete is an
543	  // intentional teardown, so we drop the volumes with it.)
544	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
545	  if (orphanVolumes.length > 0) {
546	    await db.volume.deleteMany({ where: { serverId: server.id } });
547	    for (const v of orphanVolumes) {
548	      await notify(
549	        v.userId,
550	        `Volume "${v.name}" was removed`,
551	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
552	        "/dashboard/volumes",
553	      ).catch(() => {});
554	    }
555	  }
556	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
557	  // server.delete cascade removes THIS running Job row — the success-path
558	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
559	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
560	  await db.server.delete({ where: { id: server.id } });
561	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
562	  // DELETE, which then dies on "Server not found" and the sync is never retried
563	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
564	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
