570	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
571	    await notify(
572	      server.userId,
573	      `Server ${server.hostname} reinstalled (sandbox)`,
574	      "The sandbox server was reinstalled (no real VM was touched).",
575	      `/dashboard/servers/${server.id}`
576	    );
577	    return;
578	  }
579	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
580	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
581	  // EVERY disk the vmid owns, including attached block-storage Volume disks
582	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
583	  // by that vmid, and both purge and the default destroy (which removes disks
584	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
585	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
586	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
587	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
588	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
589	  // can be re-attached after the reinstall. This runs BEFORE any status change or
590	  // destructive call, so a blocked reinstall touches nothing.
591	  //
592	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
593	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
594	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
595	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
596	  // let the worst path through: fill a volume, Detach (the UI says "Data is
597	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
598	  // Detaching is therefore NOT sufficient protection, and telling the customer to
599	  // detach was wrong advice; they must delete the volume (which destroys just
600	  // that disk, deliberately) or move it to another server first.
601	  const pinnedVolumes = await db.volume.findMany({
602	    where: { serverId: server.id },
603	  });
604	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
605	  const realPinned = pinnedVolumes.filter(
606	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
607	  );
608	  if (realPinned.length > 0) {
609	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
610	    throw new Error(
611	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
612	        `Reinstalling purges every disk this server owns — including detached volumes ` +
613	        `that are still assigned to it — and that cannot be undone.`
614	    );
615	  }
616	
617	  const { conn } = await nodeFor(server);
618	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
619	  if (server.vmid) await destroyVm(conn, server.vmid);
620	  await provision(job);
