678	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
679	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
680	    await conn.waitForTask(upid);
681	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
682	  } else {
683	    try {
684	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
685	      await conn.waitForTask(upid);
686	    } catch { /* may already be stopped */ }
687	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
688	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
