517	    const busy = await db.job.count({
518	      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
519	    });
520	    if (busy > 0) return;
521	  }
522	
523	  try {
524	    await db.$transaction(async (tx) => {
