17	export const DAY_MS = 86_400_000;
18	
19	/** Read a positive integer from the environment, falling back on a default. */
20	export function envInt(name: string, fallback: number): number {
21	  const raw = process.env[name];
22	  const n = Number(raw);
23	  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
24	}
