// ----------------------------------------------------------------------------
// NxCloud — managed, per-customer Nextcloud (Dropbox-style file hosting).
// ----------------------------------------------------------------------------
// Approach A (see nxcloud-spec.md): one Nextcloud stack per customer, isolated at
// the VM boundary and provisioned through the EXISTING Proxmox VPS provisioner
// (worker/index.ts PROVISION). NxCloud is "a VPS that boots pre-configured as
// Nextcloud", so almost everything is reused rather than rebuilt:
//
//   * BILLING + RENEWALS are fully inherited. The instance is backed by a real
//     `Server`, so it renews / duns / grace-suspends / terminates through the
//     audited VPS billing sweep (worker/billing.ts) with NO NxCloud-specific
//     money code. The backing `NxCloudPlan.serverPlan` is priced === the tier's
//     display price, so the renewal (which bills the plan's full price) collects
//     exactly the advertised monthly amount. Renewals bill FULL — the
//     first-month-free promo is shared-hosting only and never touches NxCloud.
//   * The VM lifecycle (clone → resize → cloud-init → guest-agent verify),
//     monitoring, backups, SSL, suspend/terminate all come from Server for free.
//
// The only genuinely new pieces are: this companion model (subdomain + one-time
// admin creds + app status), a cloud-init install step that stands Nextcloud up
// on the VM (worker/nxcloud.ts), a customer panel tab, and plan seed data.
enum NxCloudStatus {
  PENDING // ordered, awaiting the provisioner
  PROVISIONING // VM cloning / Nextcloud installing
  ACTIVE
  SUSPENDED // non-payment or admin (mirrors the backing Server)
  FAILED
  DELETING
}

/// A managed Nextcloud plan (a storage-led product tier). Carries the pricing +
/// marketing surface; the VM sizing the provisioner actually reads comes from the
/// linked backing `serverPlan` (kept `active = false` so it never appears in the
/// VPS storefront). The two are seeded in lockstep so display === charged.
model NxCloudPlan {
  id           String   @id @default(cuid())
  slug         String   @unique
  name         String
  priceCents   Int
  storageGB    Int // = VM disk (matches serverPlan.diskGB)
  ramMB        Int // display mirror of serverPlan.ramMB
  vcpu         Int // display mirror of serverPlan.cpuCores
  bandwidthTB  Float    @default(1)
  collabora    Boolean  @default(false) // office suite enabled on this tier
  talk         Boolean  @default(false) // video/chat enabled on this tier
  featured     Boolean  @default(false)
  tagline      String   @default("")
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  // The VPS Plan the backing VM is cloned/sized from. Reusing Plan is what lets
  // the whole Server lifecycle + the audited billing sweep work unchanged.
  serverPlanId String
  serverPlan   Plan     @relation(fields: [serverPlanId], references: [id])
  instances    NxCloudInstance[]
}

/// One customer's managed Nextcloud instance — the unit of isolation, access and
/// display. Billing rides the backing `server`; this row is the product wrapper.
model NxCloudInstance {
  id             String        @id @default(cuid())
  userId         String
  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  planId         String
  plan           NxCloudPlan   @relation(fields: [planId], references: [id])
  // The VM that runs this instance. onDelete:SetNull so tearing the VM down (a
  // customer terminate enqueues a Server DELETE) leaves a tombstone row rather
  // than orphaning the FK; the instance is normally deleted in the same action.
  serverId       String?       @unique
  server         Server?       @relation(fields: [serverId], references: [id], onDelete: SetNull)
  // Access surface. subdomain is the label under the NxCloud zone
  // (<subdomain>.nxcloud.nxeon.cloud); customDomain is a later phase.
  subdomain      String        @unique
  customDomain   String?       @unique
  sslActive      Boolean       @default(false)
  status         NxCloudStatus @default(PENDING)
  // Nextcloud admin bootstrap creds. The password is generated per instance,
  // stored ENCRYPTED, revealed to the customer ONCE then cleared — the same
  // discipline as HostingAccount.sftpPasswordEnc. An impersonating admin can
  // never exfiltrate it (assertNotImpersonating guards the reveal action).
  adminUser      String        @default("admin")
  adminPassEnc   String?
  // Usage meter, refreshed by a sweep (deferred for MVP; nullable until measured).
  storageUsedMB  Int?
  storageQuotaMB Int
  usageAt        DateTime?
  version        String? // installed Nextcloud version, once verified serving
  error          String? // last provisioning/serving issue (COMPLETED_WITH_ISSUES)
  provisionedAt  DateTime?
  createdAt      DateTime      @default(now())
  updatedAt      DateTime      @updatedAt
  tasks          NxCloudTask[]

  @@index([userId])
  @@index([status])
}

enum NxCloudTaskKind {
  RESET_ADMIN_PW // regenerate + re-apply the Nextcloud admin password
  ENABLE_APP // collabora / talk / e2ee toggle (deferred)
  UPDATE // trigger Nextcloud's updater (deferred)
}

/// A queued admin/panel operation on an instance, run by worker/nxcloud.ts. Any
/// one-time secret in `result` (e.g. a reset admin password) is shown ONCE then
/// cleared — mirrors HostingTask. Reuses HostingTaskStatus so the whole
/// pending→running→done/failed surface transfers directly.
model NxCloudTask {
  id         String            @id @default(cuid())
  instanceId String
  instance   NxCloudInstance   @relation(fields: [instanceId], references: [id], onDelete: Cascade)
  kind       NxCloudTaskKind
  status     HostingTaskStatus @default(PENDING)
  payload    String?
  result     String? // one-time secret carrier, cleared after read
  error      String?
  createdAt  DateTime          @default(now())
  updatedAt  DateTime          @updatedAt

  @@index([status])
  @@index([instanceId])
}

