88:  FAILED: { dot: "bg-red-400", text: "text-red-400" },
94:  // PENDING / SUSPENDED / DELETING are already covered above and behave the same here.
95:  ACTIVE: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
102:  const s = statusColors[status] ?? statusColors.STOPPED;

