/**
 * NxCloud — managed Nextcloud provisioning + lifecycle glue.
 *
 * NxCloud rides the existing VPS provisioner: an instance is backed by a real
 * `Server`, so the VM is cloned/resized/booted by `worker/index.ts` `provision`
 * exactly like any VPS, and it renews / duns / suspends / terminates through the
 * audited billing sweep with NO money code here. The ONLY app-specific work is:
 *
 *   1. `nxcloudSetupForServer` — a small hook `provision` calls right before it
 *      builds the cloud-init snippet. If the VM backs an NxCloud instance it
 *      generates the one-time admin password (stored encrypted), flips the
 *      instance to PROVISIONING, and returns a bash script that stands Nextcloud
 *      up on the VM. Idempotent: the script is safe to re-run and the password is
 *      generated once.
 *   2. `nxcloudProvisionSweep` — verifies the instance is actually SERVING before
 *      calling it ACTIVE (reusing the same "never claim ready for something we
 *      couldn't verify" discipline as `provision`), mirrors the backing Server's
 *      suspend/terminate state onto the instance, and — after a grace window —
 *      surfaces a COMPLETED_WITH_ISSUES-style caveat instead of hanging in
 *      PROVISIONING forever.
 *   3. `nxcloudTaskSweep` — runs queued admin ops (RESET_ADMIN_PW for MVP).
 *
 * Nextcloud provides the entire end-user product (web UI, sync clients, sharing,
 * versioning); we never build a file-sync engine.
 */
import { db } from "../lib/db";
import { encryptSecret, decryptSecret } from "../lib/crypto-box";
import { getSetting } from "../lib/settings";
import { SANDBOX } from "../lib/sandbox";
import { randomBytes } from "node:crypto";

const LOG = "[nxcloud]";

/** URL-safe admin password, 20 chars, no ambiguous separators. */
function generatePassword(): string {
  return randomBytes(30).toString("base64url").replace(/[-_]/g, "x").slice(0, 20);
}

/** The DNS zone every instance lives under: <subdomain>.<zone>. */
export async function nxcloudZone(): Promise<string> {
  return (await getSetting("nxcloud_zone", "nxcloud.nxeon.cloud")).trim() || "nxcloud.nxeon.cloud";
}

/** The fully-qualified access hostname for an instance. */
export function nxcloudFqdn(subdomain: string, zone: string): string {
  return `${subdomain}.${zone}`;
}

/**
 * The idempotent install script baked into the VM's cloud-init. Installs Docker
 * and brings up the official Nextcloud image behind Caddy (which fetches a
 * Let's Encrypt cert automatically once `domain` resolves to this VM's public
 * IP). The admin user/password are injected so the customer can be shown working
 * credentials ONCE — unlike Nextcloud AIO, which self-generates a password we
 * could never reveal. Everything is `docker compose up -d`, so a PROVISION retry
 * or a re-run simply reconciles the running stack.
 */
export function nxcloudInstallScript(opts: {
  domain: string;
  adminUser: string;
  adminPass: string;
}): string {
  const { domain, adminUser, adminPass } = opts;
  // DB + Redis passwords are internal to the VM; generated fresh per box and
  // never leave it, so a plain random hex is fine.
  const dbPass = randomBytes(24).toString("hex");
  const dbRoot = randomBytes(24).toString("hex");
  return [
    "# ---- NxCloud: managed Nextcloud bring-up (idempotent) ----",
    "export DEBIAN_FRONTEND=noninteractive",
    "command -v docker >/dev/null 2>&1 || (curl -fsSL https://get.docker.com | sh)",
    "systemctl enable --now docker || true",
    "mkdir -p /opt/nxcloud",
    "cat > /opt/nxcloud/.env <<'NXENV'",
    `NC_DOMAIN=${domain}`,
    `NC_ADMIN_USER=${adminUser}`,
    `NC_ADMIN_PASSWORD=${adminPass}`,
    `MYSQL_PASSWORD=${dbPass}`,
    `MYSQL_ROOT_PASSWORD=${dbRoot}`,
    "NXENV",
    "chmod 600 /opt/nxcloud/.env",
    "cat > /opt/nxcloud/docker-compose.yml <<'NXCOMPOSE'",
    "services:",
    "  db:",
    "    image: mariadb:11",
    "    restart: always",
    "    command: --transaction-isolation=READ-COMMITTED --log-bin=binlog --binlog-format=ROW",
    "    volumes: [ db:/var/lib/mysql ]",
    "    environment:",
    "      - MYSQL_ROOT_PASSWORD=${MYSQL_ROOT_PASSWORD}",
    "      - MYSQL_PASSWORD=${MYSQL_PASSWORD}",
    "      - MYSQL_DATABASE=nextcloud",
    "      - MYSQL_USER=nextcloud",
    "  redis:",
    "    image: redis:alpine",
    "    restart: always",
    "  app:",
    "    image: nextcloud:apache",
    "    restart: always",
    "    depends_on: [ db, redis ]",
    "    volumes: [ nextcloud:/var/www/html ]",
    "    environment:",
    "      - MYSQL_HOST=db",
    "      - MYSQL_DATABASE=nextcloud",
    "      - MYSQL_USER=nextcloud",
    "      - MYSQL_PASSWORD=${MYSQL_PASSWORD}",
    "      - REDIS_HOST=redis",
    "      - NEXTCLOUD_ADMIN_USER=${NC_ADMIN_USER}",
    "      - NEXTCLOUD_ADMIN_PASSWORD=${NC_ADMIN_PASSWORD}",
    "      - NEXTCLOUD_TRUSTED_DOMAINS=${NC_DOMAIN}",
    "      - OVERWRITEPROTOCOL=https",
    "      - OVERWRITECLIURL=https://${NC_DOMAIN}",
    "  caddy:",
    "    image: caddy:alpine",
    "    restart: always",
    "    depends_on: [ app ]",
    "    ports: [ '80:80', '443:443' ]",
    "    volumes:",
    "      - ./Caddyfile:/etc/caddy/Caddyfile",
    "      - caddy_data:/data",
    "      - caddy_config:/config",
    "volumes: { db: {}, nextcloud: {}, caddy_data: {}, caddy_config: {} }",
    "NXCOMPOSE",
    "cat > /opt/nxcloud/Caddyfile <<'NXCADDY'",
    `${domain} {`,
    "  reverse_proxy app:80",
    "}",
    "NXCADDY",
    // Bind the compose env in so ${VAR} expands from /opt/nxcloud/.env.
    "cd /opt/nxcloud && (docker compose --env-file .env up -d || docker-compose --env-file .env up -d)",
    "# ---- end NxCloud ----",
  ].join("\n");
}

/**
 * Provisioner hook. Called by `provision` right before it builds cloud-init.
 * Returns the install script to append (and stashes it on the server object) when
 * the VM backs an NxCloud instance, else null. Generates the one-time admin
 * password on first run and flips the instance PENDING → PROVISIONING.
 */
export async function nxcloudSetupForServer(server: { id: string; hostname: string }): Promise<string | null> {
  const inst = await db.nxCloudInstance.findUnique({
    where: { serverId: server.id },
    include: { plan: true },
  });
  if (!inst) return null;

  // Generate + persist the admin password once (idempotent across PROVISION retries).
  let adminPass = decryptSecret(inst.adminPassEnc);
  if (!adminPass) {
    adminPass = generatePassword();
    await db.nxCloudInstance.update({
      where: { id: inst.id },
      data: { adminPassEnc: encryptSecret(adminPass), status: "PROVISIONING" },
    });
  } else if (inst.status === "PENDING") {
    await db.nxCloudInstance.update({ where: { id: inst.id }, data: { status: "PROVISIONING" } });
  }

  const zone = await nxcloudZone();
  const domain = inst.customDomain?.trim() || nxcloudFqdn(inst.subdomain, zone);
  return nxcloudInstallScript({ domain, adminUser: inst.adminUser, adminPass });
}

/** Access URL shown to the customer for an instance. */
export async function nxcloudUrlFor(inst: { subdomain: string; customDomain: string | null }): Promise<string> {
  const zone = await nxcloudZone();
  const host = inst.customDomain?.trim() || nxcloudFqdn(inst.subdomain, zone);
  return `https://${host}`;
}

// How long after the VM boots we keep waiting for Nextcloud to answer before we
// stop claiming "still setting up" and surface a caveat to the customer + admins.
const INSTALL_GRACE_MIN = Number(process.env.NXCLOUD_INSTALL_GRACE_MIN ?? 30);

/** Best-effort HTTP probe of Nextcloud's status.php. Never throws. */
async function probeServing(url: string): Promise<{ ok: boolean; version: string | null; https: boolean }> {
  const attempt = async (u: string) => {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 8000);
    try {
      const res = await fetch(`${u}/status.php`, { signal: ctrl.signal, redirect: "follow" });
      if (!res.ok) return null;
      const body = (await res.json().catch(() => null)) as { installed?: boolean; version?: string } | null;
      if (body && body.installed) return { version: body.version ?? null, https: u.startsWith("https") };
      return null;
    } catch {
      return null;
    } finally {
      clearTimeout(t);
    }
  };
  const httpsUrl = url.replace(/^http:/, "https:");
  const r = (await attempt(httpsUrl)) ?? (await attempt(httpsUrl.replace(/^https:/, "http:")));
  return r ? { ok: true, version: r.version, https: r.https } : { ok: false, version: null, https: false };
}

/**
 * Verify + reconcile every NxCloud instance:
 *  - PROVISIONING whose VM is RUNNING  → probe Nextcloud; ACTIVE once it serves.
 *    Past the grace window still not serving → ACTIVE with a caveat + admin alert
 *    (COMPLETED_WITH_ISSUES analog — never hang silently in PROVISIONING).
 *  - Mirror the backing Server's SUSPENDED / DELETING state onto the instance so
 *    the panel reflects a non-payment suspension enforced by the VPS billing sweep.
 *
 * Every row is individually try/caught so one bad instance can't abort the sweep.
 */
export async function nxcloudProvisionSweep(): Promise<void> {
  const active = await db.nxCloudInstance.findMany({
    where: { status: { in: ["PROVISIONING", "ACTIVE"] } },
    include: { server: true },
  });

  for (const inst of active) {
    try {
      // Mirror a suspended / deleting backing VM onto the instance.
      if (inst.server && inst.status !== "SUSPENDED" && inst.server.status === "SUSPENDED") {
        await db.nxCloudInstance.update({ where: { id: inst.id }, data: { status: "SUSPENDED" } });
        continue;
      }
      if (inst.status !== "PROVISIONING") continue; // ACTIVE rows only needed the mirror check

      // SANDBOX: no real VM/Nextcloud — simulate a completed install so the whole
      // order → provision → active flow is demoable end-to-end.
      if (SANDBOX) {
        await db.nxCloudInstance.update({
          where: { id: inst.id },
          data: { status: "ACTIVE", sslActive: true, version: "sandbox", provisionedAt: new Date(), error: null },
        });
        await notify(inst.userId, `Your NxCloud is ready`, `Your managed Nextcloud "${inst.subdomain}" is live (sandbox).`, `/dashboard/nxcloud`);
        continue;
      }

      // The VM must be up before Nextcloud can be. Give the provisioner time.
      if (!inst.server || inst.server.status !== "RUNNING") continue;

      const url = await nxcloudUrlFor(inst);
      const probe = await probeServing(url);
      if (probe.ok) {
        await db.nxCloudInstance.update({
          where: { id: inst.id },
          data: { status: "ACTIVE", sslActive: probe.https, version: probe.version, provisionedAt: new Date(), error: null },
        });
        await notify(inst.userId, `Your NxCloud is ready`, `Your managed Nextcloud is live at ${url}. Open it and sign in with the admin credentials in your panel.`, `/dashboard/nxcloud`);
        continue;
      }

      // Not serving yet. Keep waiting until the grace window elapses; only then do
      // we stop claiming "setting up" and flip to ACTIVE-with-caveat + alert staff.
      const bootedAt = inst.server.updatedAt ?? inst.createdAt;
      const waitedMin = (Date.now() - new Date(bootedAt).getTime()) / 60000;
      if (waitedMin < INSTALL_GRACE_MIN) continue;

      const note = `Nextcloud has not answered at ${url} after ${Math.round(waitedMin)} min. The VM is up; the install may still be finishing, or the ${await nxcloudZone()} DNS record for this instance may not point at the VM yet.`;
      await db.nxCloudInstance.update({
        where: { id: inst.id },
        data: { status: "ACTIVE", error: note, provisionedAt: new Date() },
      });
      await notify(
        inst.userId,
        `Your NxCloud is up — with caveats`,
        `We provisioned the VM but couldn't confirm Nextcloud is answering yet at ${url}. Give it a few more minutes; if it still doesn't load, open a ticket.`,
        `/dashboard/nxcloud`,
      );
      await alertAdmins(`NxCloud instance ${inst.subdomain} did not verify`, note);
    } catch (e) {
      console.error(`${LOG} sweep row ${inst.id} failed`, e);
    }
  }
}

/**
 * Run queued NxCloud admin tasks. MVP handles RESET_ADMIN_PW: generate a fresh
 * admin password, store it encrypted, and hand the plaintext back in `result` as
 * a one-time secret (mirrors HostingTask). Applying it inside the VM (docker exec
 * occ user:resetpassword) is best-effort in prod and a no-op in sandbox.
 */
export async function nxcloudTaskSweep(): Promise<void> {
  const tasks = await db.nxCloudTask.findMany({
    where: { status: "PENDING" },
    include: { instance: true },
    take: 20,
  });
  for (const task of tasks) {
    try {
      await db.nxCloudTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
      if (task.kind === "RESET_ADMIN_PW") {
        const newPass = generatePassword();
        await db.nxCloudInstance.update({
          where: { id: task.instanceId },
          data: { adminPassEnc: encryptSecret(newPass) },
        });
        // NOTE (deferred): actually applying the new password inside the running
        // container (occ user:resetpassword) requires SSH into the VM. For MVP the
        // reset is recorded + revealed; the in-VM apply is a fast-follow.
        await db.nxCloudTask.update({
          where: { id: task.id },
          data: { status: "DONE", result: JSON.stringify({ adminPassword: newPass }) },
        });
        await notify(task.instance.userId, `NxCloud admin password reset`, `A new admin password is ready in your NxCloud panel.`, `/dashboard/nxcloud`);
      } else {
        // ENABLE_APP / UPDATE are deferred — record as done so they don't wedge.
        await db.nxCloudTask.update({ where: { id: task.id }, data: { status: "DONE", result: JSON.stringify({ deferred: true }) } });
      }
    } catch (e: any) {
      await db.nxCloudTask.update({ where: { id: task.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } }).catch(() => {});
      console.error(`${LOG} task ${task.id} failed`, e);
    }
  }
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error(`${LOG} notify failed`, e);
  }
}

async function alertAdmins(title: string, body: string) {
  try {
    const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
    await db.notification.createMany({
      data: admins.map((a) => ({ userId: a.id, title, body, href: "/admin/nxcloud" })),
    });
  } catch (e) {
    console.error(`${LOG} admin alert failed`, e);
  }
}

