/**
 * NxCloud pure helpers — subdomain rules + URL building. No `db`, no I/O, so both
 * the worker (worker/nxcloud.ts) and the server actions/pages can share one source
 * of truth for what a valid instance hostname is.
 */

/** The DNS zone every instance lives under when no custom domain is set. */
export const NXCLOUD_DEFAULT_ZONE = "nxcloud.nxeon.cloud";

export function normalizeSubdomain(raw: string): string {
  return (raw ?? "").trim().toLowerCase();
}

/**
 * A DNS label: lowercase letters/digits/hyphens, 3–32 chars, no leading/trailing
 * hyphen. Same shape as a VPS hostname but lowercased and reserved-word screened.
 */
export function isValidSubdomainLabel(label: string): boolean {
  if (label.length < 3 || label.length > 32) return false;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/.test(label)) return false;
  return !RESERVED_SUBDOMAINS.has(label);
}

const RESERVED_SUBDOMAINS = new Set([
  "www", "admin", "root", "api", "app", "mail", "smtp", "imap", "ns", "ns1", "ns2",
  "test", "staging", "dev", "nextcloud", "cloud", "nxcloud", "status", "support",
]);

/** <subdomain>.<zone> */
export function nxcloudFqdn(subdomain: string, zone: string = NXCLOUD_DEFAULT_ZONE): string {
  return `${subdomain}.${zone}`;
}

/** The https access URL for a hostname. */
export function nxcloudUrl(host: string): string {
  return `https://${host}`;
}

