"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";
import { invoiceCreateData } from "./invoices";
import { decryptSecret } from "./crypto-box";
import { emailVerificationError } from "./email-verification";
import { getSetting } from "./settings";
import {
  NXCLOUD_DEFAULT_ZONE,
  normalizeSubdomain,
  isValidSubdomainLabel,
  nxcloudFqdn,
  nxcloudUrl,
} from "./nxcloud";

export type NxCloudResult = { ok?: boolean; error?: string; instanceId?: string };

// The instance states that reserve a subdomain / count as live.
const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;

/** Least-loaded enabled+online Proxmox node by RAM headroom (mirrors lib/order.ts scheduleNode). */
async function scheduleNode(planRamMB: number): Promise<string | null> {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      return { id: n.id, free: n.capacityRamMB - used };
    }),
  );
  loads.sort((a, b) => b.free - a.free);
  return loads[0].id;
}

/**
 * Order a managed Nextcloud (NxCloud) instance.
 *
 * MONEY SAFETY — this mirrors the audited VPS/hosting order discipline:
 *   - no spending while impersonating; verified email required;
 *   - the wallet is charged the FULL displayed monthly price (NO first-month-free —
 *     that promo is shared-hosting only), in the SAME transaction that creates the
 *     records, so a rolled-back charge leaves no instance and no invoice;
 *   - the amount charged is exactly `plan.priceCents`, which is also what the
 *     backing Server renews at (its `serverPlan.priceCents` is seeded equal), so
 *     displayed === charged === renewed.
 *
 * The instance is backed by a real `Server`, created here with a PROVISION job.
 * The worker clones/sizes the VM and bakes in the Nextcloud install (worker/nxcloud.ts);
 * the instance flips to ACTIVE once it verifies serving.
 */
export async function orderNxCloud(planId: string, subdomainRaw: string): Promise<NxCloudResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const subdomain = normalizeSubdomain(subdomainRaw);
  if (!subdomain) return { error: "Choose a subdomain for your cloud." };
  if (!isValidSubdomainLabel(subdomain)) {
    return { error: "Subdomain: 3–32 lowercase letters, digits or hyphens (not a reserved word)." };
  }

  const plan = await db.nxCloudPlan.findUnique({ where: { id: planId }, include: { serverPlan: true } });
  if (!plan || !plan.active) return { error: "That NxCloud plan isn’t available." };
  if (!plan.serverPlan) return { error: "This plan isn’t fully configured yet — please contact support." };

  // The Nextcloud OS image the VM clones from (seeded by prisma/seed-nxcloud.ts).
  const osTemplate = await db.osTemplate.findUnique({ where: { slug: "nextcloud" } });
  if (!osTemplate) return { error: "NxCloud isn’t available yet — the Nextcloud image hasn’t been seeded." };

  // Subdomain is globally unique across all customers (it's a public hostname).
  const taken = await db.nxCloudInstance.findFirst({
    where: { subdomain, status: { in: [...LIVE_STATES] } },
    select: { id: true, userId: true },
  });
  if (taken) {
    return {
      error:
        taken.userId === user.id
          ? "You already have a cloud with that subdomain."
          : "That subdomain is taken — try another.",
    };
  }

  const chargeCents = plan.priceCents;
  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };

  const nodeId = await scheduleNode(plan.serverPlan.ramMB);
  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
  const fqdn = nxcloudFqdn(subdomain, zone);

  let instanceId = "";
  try {
    await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `NxCloud: ${plan.name} (${fqdn})`,
        },
      });
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: `NxCloud: ${plan.name} (${fqdn})`,
          status: "PAID",
          period: { start: new Date(), end: addMonths(new Date(), 1) },
          lineItems: [
            { description: `${plan.name} — managed Nextcloud (${fqdn})`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
          ],
        }),
      });
      // The backing VM. A normal Server — it renews / duns / suspends / monitors
      // through the exact same audited machinery as a VPS. VM snapshot backups are
      // ON by default (data-loss safety, spec §6); a public IP is requested so the
      // instance is reachable by hostname for auto-TLS.
      const server = await tx.server.create({
        data: {
          name: subdomain,
          hostname: subdomain,
          userId: user.id,
          planId: plan.serverPlanId,
          osTemplateId: osTemplate.id,
          nodeId,
          autoBackup: true,
          backupIntervalHours: 24,
          termMonths: 1,
          // Sold at full price — 0% off — so no later proration can claw a discount
          // that was never given (see Server.termPromoPercent).
          termPromoPercent: 0,
          wantsDedicatedIp: true,
          isFree: false,
          expiresAt: addMonths(new Date(), 1),
        },
      });
      const inst = await tx.nxCloudInstance.create({
        data: {
          userId: user.id,
          planId: plan.id,
          serverId: server.id,
          subdomain,
          status: "PENDING",
          adminUser: "admin",
          storageQuotaMB: plan.storageGB * 1024,
        },
      });
      instanceId = inst.id;
      await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
  }

  await db.auditLog
    .create({ data: { userId: user.id, action: "nxcloud.order", detail: `${plan.name} · ${fqdn}` } })
    .catch(() => {});
  revalidatePath("/dashboard/nxcloud");
  return { ok: true, instanceId };
}

export type NxCloudInstanceView = {
  id: string;
  subdomain: string;
  url: string;
  planName: string;
  status: string;
  adminUser: string;
  hasPassword: boolean;
  storageQuotaMB: number;
  storageUsedMB: number | null;
  usageAt: string | null;
  sslActive: boolean;
  version: string | null;
  error: string | null;
  expiresAt: string | null;
  createdAt: string;
};

function toView(
  a: {
    id: string; subdomain: string; customDomain: string | null; status: string; adminUser: string;
    adminPassEnc: string | null; storageQuotaMB: number; storageUsedMB: number | null; usageAt: Date | null;
    sslActive: boolean; version: string | null; error: string | null; createdAt: Date;
    plan: { name: string }; server: { expiresAt: Date | null } | null;
  },
  zone: string,
): NxCloudInstanceView {
  const host = a.customDomain?.trim() || nxcloudFqdn(a.subdomain, zone);
  return {
    id: a.id,
    subdomain: a.subdomain,
    url: nxcloudUrl(host),
    planName: a.plan.name,
    status: a.status,
    adminUser: a.adminUser,
    hasPassword: !!a.adminPassEnc,
    storageQuotaMB: a.storageQuotaMB,
    storageUsedMB: a.storageUsedMB ?? null,
    usageAt: a.usageAt?.toISOString() ?? null,
    sslActive: a.sslActive,
    version: a.version,
    error: a.error,
    expiresAt: a.server?.expiresAt?.toISOString() ?? null,
    createdAt: a.createdAt.toISOString(),
  };
}

/** The current user's NxCloud instances (newest first). */
export async function listNxcloudInstances(): Promise<NxCloudInstanceView[]> {
  const user = await requireUser();
  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
  const rows = await db.nxCloudInstance.findMany({
    where: { userId: user.id },
    include: { plan: { select: { name: true } }, server: { select: { expiresAt: true } } },
    orderBy: { createdAt: "desc" },
  });
  return rows.map((r) => toView(r, zone));
}

/**
 * Reveal the current Nextcloud admin password to the OWNER (or an admin who is NOT
 * impersonating). Same discipline as the SFTP-password reveal in
 * lib/actions-hosting.ts — an impersonating admin must never exfiltrate it.
 */
export async function revealNxcloudAdminPassword(instanceId: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const inst = await db.nxCloudInstance.findUnique({
    where: { id: instanceId },
    select: { userId: true, adminPassEnc: true },
  });
  if (!inst) return { error: "Not found." };
  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const pw = inst.adminPassEnc ? decryptSecret(inst.adminPassEnc) : null;
  if (!pw) return { error: "No password on record yet — your cloud is still being set up." };
  return { password: pw };
}

/** Queue an admin-password reset for an instance (worker regenerates + re-applies). */
export async function resetNxcloudAdminPassword(instanceId: string): Promise<NxCloudResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, status: true } });
  if (!inst) return { error: "Not found." };
  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (inst.status !== "ACTIVE") return { error: "Wait until your cloud is active, then reset the password." };
  await db.nxCloudTask.create({ data: { instanceId, kind: "RESET_ADMIN_PW" } });
  revalidatePath("/dashboard/nxcloud");
  return { ok: true };
}

/**
 * Terminate an instance: destroy the backing VM (enqueue a Server DELETE — the
 * audited teardown that stops billing and purges the disk) and remove the
 * instance record. Irreversible; the customer's files go with the VM.
 */
export async function terminateNxcloud(instanceId: string): Promise<NxCloudResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, serverId: true } });
  if (!inst) return { error: "Not found." };
  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (inst.serverId) {
    await db.job.create({ data: { type: "DELETE", serverId: inst.serverId } });
  }
  // Drop the wrapper row (tasks cascade). The DELETE job tears the VM down.
  await db.nxCloudInstance.delete({ where: { id: instanceId } });
  await db.auditLog.create({ data: { userId: user.id, action: "nxcloud.terminate", detail: instanceId } }).catch(() => {});
  revalidatePath("/dashboard/nxcloud");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Admin visibility
// ---------------------------------------------------------------------------

export type NxCloudAdminView = NxCloudInstanceView & {
  userEmail: string;
  serverId: string | null;
};

/** Every NxCloud instance across the fleet, for /admin/nxcloud. ADMIN-only. */
export async function adminListNxcloud(): Promise<NxCloudAdminView[]> {
  await requireArea("fleet");
  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
  const rows = await db.nxCloudInstance.findMany({
    include: {
      plan: { select: { name: true } },
      server: { select: { expiresAt: true } },
      user: { select: { email: true } },
    },
    orderBy: { createdAt: "desc" },
  });
  return rows.map((r) => ({ ...toView(r, zone), userEmail: r.user.email, serverId: r.serverId }));
}

/**
 * NxCloud seed — the managed-Nextcloud product catalog.
 *
 * For each tier this creates TWO rows, kept in lockstep so displayed === charged:
 *   1. a backing `Plan` (slug `nxcloud-<tier>`, `active:false` so it NEVER shows in
 *      the VPS deploy wizard) — this is the VM sizing the provisioner reads and the
 *      price the audited VPS billing sweep renews at;
 *   2. an `NxCloudPlan` (the storefront tier) linked to that Plan, priced equal.
 *
 * It also seeds the `nextcloud` OsTemplate the backing VM clones from
 * (`active:false` — customers order it through the NxCloud product, not as a raw
 * VPS image). The per-instance Nextcloud install is injected by worker/nxcloud.ts,
 * so this template carries no setupScript.
 *
 * Idempotent (upsert by slug). Safe to re-run.
 * Run: NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed-nxcloud.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

// Ubuntu 24.04 base template VMID on the node (see prisma/catalog.ts BASE).
const UBUNTU_2404_VMID = 9000;

type Tier = {
  slug: string;
  name: string;
  priceCents: number;
  storageGB: number;
  ramMB: number;
  vcpu: number;
  bandwidthTB: number;
  collabora: boolean;
  talk: boolean;
  featured: boolean;
  tagline: string;
  sortOrder: number;
};

// Launch tiers (spec §3). Prices are the FULL monthly rate — NxCloud never gets
// the shared-hosting first-month-free promo.
const TIERS: Tier[] = [
  { slug: "personal", name: "Personal", priceCents: 599, storageGB: 100, ramMB: 2048, vcpu: 1, bandwidthTB: 1, collabora: false, talk: false, featured: false, tagline: "Your own private cloud — 100 GB, unlimited devices.", sortOrder: 0 },
  { slug: "family", name: "Family / Pro", priceCents: 1199, storageGB: 500, ramMB: 4096, vcpu: 2, bandwidthTB: 2, collabora: false, talk: false, featured: true, tagline: "500 GB and unlimited people on your own box.", sortOrder: 1 },
  { slug: "team", name: "Team", priceCents: 1999, storageGB: 1000, ramMB: 4096, vcpu: 2, bandwidthTB: 3, collabora: false, talk: false, featured: false, tagline: "1 TB, unlimited internal users, sync everywhere.", sortOrder: 2 },
  { slug: "business", name: "Business", priceCents: 3499, storageGB: 2000, ramMB: 8192, vcpu: 4, bandwidthTB: 5, collabora: true, talk: true, featured: false, tagline: "2 TB with Office + Talk built in. Priority support.", sortOrder: 3 },
];

async function main() {
  // 1) The Nextcloud OS image the backing VM clones from.
  await db.osTemplate.upsert({
    where: { slug: "nextcloud" },
    update: { name: "Nextcloud", category: "APPLICATION", family: "ubuntu", version: "24.04", baseVmid: UBUNTU_2404_VMID, minRamMB: 2048, minDiskGB: 30, active: false },
    create: {
      slug: "nextcloud",
      name: "Nextcloud",
      category: "APPLICATION",
      family: "ubuntu",
      version: "24.04",
      logo: "nextcloud",
      vmid: UBUNTU_2404_VMID,
      baseVmid: UBUNTU_2404_VMID,
      // The install is injected per-instance (with the customer's admin creds) by
      // worker/nxcloud.ts, so no static setupScript here.
      setupScript: null,
      minRamMB: 2048,
      minDiskGB: 30,
      active: false, // hidden from the VPS wizard — ordered via the NxCloud product
      sortOrder: 900,
    },
  });
  console.log("  osTemplate  nextcloud (hidden application image) ready");

  // 2) Each tier: backing Plan (hidden) + NxCloudPlan (storefront), priced equal.
  let n = 0;
  for (const t of TIERS) {
    const planSlug = `nxcloud-${t.slug}`;
    const serverPlan = await db.plan.upsert({
      where: { slug: planSlug },
      update: { name: `NxCloud ${t.name}`, cpuCores: t.vcpu, ramMB: t.ramMB, diskGB: t.storageGB, bandwidthTB: t.bandwidthTB, priceCents: t.priceCents, active: false },
      create: {
        slug: planSlug,
        name: `NxCloud ${t.name}`,
        cpuCores: t.vcpu,
        ramMB: t.ramMB,
        diskGB: t.storageGB,
        bandwidthTB: t.bandwidthTB,
        priceCents: t.priceCents,
        storageTier: "nvme",
        active: false, // never orderable as a raw VPS
        sortOrder: 900 + t.sortOrder,
      },
    });

    await db.nxCloudPlan.upsert({
      where: { slug: t.slug },
      update: {
        name: t.name,
        priceCents: t.priceCents,
        storageGB: t.storageGB,
        ramMB: t.ramMB,
        vcpu: t.vcpu,
        bandwidthTB: t.bandwidthTB,
        collabora: t.collabora,
        talk: t.talk,
        featured: t.featured,
        tagline: t.tagline,
        active: true,
        sortOrder: t.sortOrder,
        serverPlanId: serverPlan.id,
      },
      create: {
        slug: t.slug,
        name: t.name,
        priceCents: t.priceCents,
        storageGB: t.storageGB,
        ramMB: t.ramMB,
        vcpu: t.vcpu,
        bandwidthTB: t.bandwidthTB,
        collabora: t.collabora,
        talk: t.talk,
        featured: t.featured,
        tagline: t.tagline,
        active: true,
        sortOrder: t.sortOrder,
        serverPlanId: serverPlan.id,
      },
    });
    n++;
    console.log(`  nxcloud     ${t.name.padEnd(12)} $${(t.priceCents / 100).toFixed(2)}/mo · ${t.storageGB} GB · ${t.ramMB / 1024} GB RAM · ${t.vcpu} vCPU`);
  }

  const total = await db.nxCloudPlan.count();
  console.log(`\nNxCloudPlans: ${n} upserted. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

