"use client";

import { useState } from "react";
import {
  orderNxCloud,
  revealNxcloudAdminPassword,
  resetNxcloudAdminPassword,
  terminateNxcloud,
  type NxCloudInstanceView,
} from "@/lib/actions-nxcloud";
import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";

type PlanView = {
  id: string;
  slug: string;
  name: string;
  priceCents: number;
  storageGB: number;
  ramMB: number;
  vcpu: number;
  collabora: boolean;
  talk: boolean;
  featured: boolean;
  tagline: string;
};

function storageLabel(gb: number): string {
  return gb >= 1000 ? `${gb / 1000} TB` : `${gb} GB`;
}

export function NxcloudClient({
  plans,
  instances,
  zone,
}: {
  plans: PlanView[];
  instances: NxCloudInstanceView[];
  zone: string;
}) {
  const [subdomain, setSubdomain] = useState("");
  const [planId, setPlanId] = useState(plans.find((p) => p.featured)?.id ?? plans[0]?.id ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [ok, setOk] = useState("");

  async function order() {
    if (!planId || !subdomain.trim()) return;
    setBusy(true);
    setError("");
    setOk("");
    try {
      const res = await orderNxCloud(planId, subdomain.trim());
      if (res.error) setError(res.error);
      else {
        setOk("Your cloud is being set up — this takes a few minutes.");
        setSubdomain("");
        setTimeout(() => window.location.reload(), 900);
      }
    } catch {
      setError("Something went wrong. Your wallet was not charged — try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-xl font-semibold">NxCloud</h1>
        <p className="mt-1 text-sm text-slate-400">
          Your own private cloud — a fully managed Nextcloud on a dedicated VM. Store, sync and share files across all
          your devices, with your own subdomain and automatic HTTPS. We run the server; you own the data.
        </p>
      </div>

      {instances.length > 0 ? (
        <div className="space-y-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your clouds</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {instances.map((inst) => (
              <InstanceCard key={inst.id} inst={inst} />
            ))}
          </div>
        </div>
      ) : (
        <EmptyState
          title="No clouds yet"
          sub="Pick a plan below, choose a subdomain, and we’ll stand up your private Nextcloud in a few minutes."
        />
      )}

      {/* Order a new instance. */}
      <div className="card">
        <h2 className="mb-1 font-semibold">{instances.length ? "Launch another cloud" : "Launch your cloud"}</h2>
        <p className="mb-3 text-xs text-slate-500">
          Each cloud is an isolated VM running managed Nextcloud — unlimited users within your instance, and full
          desktop/mobile sync clients.
        </p>
        {error && <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
        {ok && <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{ok}</div>}

        {plans.length === 0 ? (
          <p className="text-sm text-slate-400">No NxCloud plans are available yet. Check back soon.</p>
        ) : (
          <>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
              {plans.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => setPlanId(p.id)}
                  className={`flex flex-col rounded-2xl border p-4 text-left transition ${
                    planId === p.id
                      ? "border-brand-500/60 bg-brand-500/10"
                      : "border-white/[0.08] bg-navy-850/60 hover:border-brand-500/30"
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-semibold text-white">{p.name}</span>
                    {p.featured && <Badge tone="brand">popular</Badge>}
                  </div>
                  <span className="mt-1 text-2xl font-bold text-white">
                    {fmtMoney(p.priceCents)}
                    <span className="text-xs font-normal text-slate-400">/mo</span>
                  </span>
                  <ul className="mt-2 space-y-0.5 text-xs text-slate-300">
                    <li>{storageLabel(p.storageGB)} storage</li>
                    <li>{p.ramMB / 1024} GB RAM · {p.vcpu} vCPU</li>
                    {p.collabora && <li>Office (Collabora)</li>}
                    {p.talk && <li>Talk video/chat</li>}
                  </ul>
                </button>
              ))}
            </div>

            <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-end">
              <label className="flex-1">
                <span className="mb-1 block text-xs font-medium text-slate-400">Subdomain</span>
                <div className="flex items-center rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2 text-sm">
                  <input
                    value={subdomain}
                    onChange={(e) => setSubdomain(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ""))}
                    placeholder="mycloud"
                    maxLength={32}
                    className="w-full bg-transparent text-white outline-none placeholder:text-slate-600"
                  />
                  <span className="whitespace-nowrap text-slate-500">.{zone}</span>
                </div>
              </label>
              <button onClick={order} disabled={busy || !subdomain.trim()} className="btn-primary sm:w-auto">
                {busy ? "Launching…" : "Launch cloud"}
              </button>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Billed monthly to your wallet. Renews at the same price — no first-month promo on NxCloud.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

function InstanceCard({ inst }: { inst: NxCloudInstanceView }) {
  const [pw, setPw] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [busy, setBusy] = useState(false);

  async function reveal() {
    setBusy(true);
    const res = await revealNxcloudAdminPassword(inst.id);
    setBusy(false);
    if (res.error) setMsg(res.error);
    else setPw(res.password ?? "");
  }
  async function reset() {
    if (!confirm("Reset the Nextcloud admin password for this cloud?")) return;
    setBusy(true);
    const res = await resetNxcloudAdminPassword(inst.id);
    setBusy(false);
    setMsg(res.error ?? "Password reset queued — check back in a moment.");
    setPw(null);
  }
  async function terminate() {
    if (!confirm("Permanently delete this cloud and ALL its files? This cannot be undone.")) return;
    setBusy(true);
    const res = await terminateNxcloud(inst.id);
    setBusy(false);
    if (res.error) setMsg(res.error);
    else window.location.reload();
  }

  const usedPct =
    inst.storageUsedMB != null && inst.storageQuotaMB > 0
      ? Math.min(100, Math.round((inst.storageUsedMB / inst.storageQuotaMB) * 100))
      : null;

  return (
    <div className="card card-hover">
      <div className="flex items-start justify-between">
        <div>
          <div className="font-semibold text-white">{inst.subdomain}</div>
          <div className="text-xs text-slate-500">{inst.planName}</div>
        </div>
        <StatusDot status={inst.status} />
      </div>

      <div className="mt-3 flex flex-wrap gap-2">
        {inst.sslActive && <Badge tone="green">HTTPS</Badge>}
        {inst.version && <Badge tone="slate">Nextcloud {inst.version}</Badge>}
      </div>

      {usedPct != null && (
        <div className="mt-3">
          <div className="mb-1 flex justify-between text-xs text-slate-400">
            <span>Storage</span>
            <span>
              {Math.round((inst.storageUsedMB ?? 0) / 1024)} / {Math.round(inst.storageQuotaMB / 1024)} GB
            </span>
          </div>
          <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
            <div className="h-full bg-gradient-to-r from-accent-blue to-brand-500" style={{ width: `${usedPct}%` }} />
          </div>
        </div>
      )}

      {inst.error && <p className="mt-3 text-xs text-amber-300">{inst.error}</p>}

      {inst.status === "ACTIVE" && (
        <div className="mt-4 space-y-2 rounded-xl border border-white/[0.06] bg-navy-950/50 p-3 text-xs">
          <div className="flex justify-between">
            <span className="text-slate-500">Admin user</span>
            <span className="font-mono text-slate-300">{inst.adminUser}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-slate-500">Admin password</span>
            {pw != null ? (
              <span className="select-all font-mono text-slate-200">{pw}</span>
            ) : (
              <button onClick={reveal} disabled={busy} className="text-brand-300 hover:underline">
                {busy ? "…" : "Reveal"}
              </button>
            )}
          </div>
        </div>
      )}

      {msg && <p className="mt-2 text-xs text-slate-400">{msg}</p>}

      <div className="mt-4 flex flex-wrap gap-2">
        <a
          href={inst.url}
          target="_blank"
          rel="noopener noreferrer"
          className={`btn-primary text-center text-sm ${inst.status === "ACTIVE" ? "" : "pointer-events-none opacity-50"}`}
        >
          Open your cloud
        </a>
        {inst.status === "ACTIVE" && (
          <button onClick={reset} disabled={busy} className="btn-secondary text-sm">
            Reset admin password
          </button>
        )}
        <button onClick={terminate} disabled={busy} className="btn-secondary text-sm !border-red-500/30 !text-red-300">
          Delete
        </button>
      </div>
    </div>
  );
}

