import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { adminListNxcloud } from "@/lib/actions-nxcloud";

export const dynamic = "force-dynamic";

export default async function AdminNxcloudPage() {
  await requireArea("fleet");
  const [instances, plans] = await Promise.all([
    adminListNxcloud(),
    db.nxCloudPlan.findMany({ orderBy: { sortOrder: "asc" } }),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader title="NxCloud" sub="Managed per-customer Nextcloud instances — each backed by an isolated VM." />

      {/* Plan tiers */}
      <div className="card">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">Plans</h2>
        {plans.length === 0 ? (
          <p className="text-sm text-slate-400">
            No NxCloud plans seeded yet. Run <code className="text-brand-300">npx tsx prisma/seed-nxcloud.ts</code>.
          </p>
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {plans.map((p) => (
              <div key={p.id} className="rounded-xl border border-white/[0.08] bg-navy-850/60 p-3 text-sm">
                <div className="flex items-center justify-between">
                  <span className="font-semibold text-white">{p.name}</span>
                  {!p.active && <Badge tone="slate">inactive</Badge>}
                </div>
                <div className="mt-1 text-lg font-bold text-white">
                  {fmtMoney(p.priceCents)}
                  <span className="text-xs font-normal text-slate-400">/mo</span>
                </div>
                <div className="mt-1 text-xs text-slate-400">
                  {p.storageGB >= 1000 ? `${p.storageGB / 1000} TB` : `${p.storageGB} GB`} · {p.ramMB / 1024} GB RAM · {p.vcpu} vCPU
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Instances */}
      <div className="card overflow-x-auto">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">
          Instances ({instances.length})
        </h2>
        {instances.length === 0 ? (
          <p className="text-sm text-slate-400">No NxCloud instances yet.</p>
        ) : (
          <table className="w-full text-left text-sm">
            <thead className="text-xs uppercase tracking-wide text-slate-500">
              <tr className="border-b border-white/[0.06]">
                <th className="py-2 pr-4">Subdomain</th>
                <th className="py-2 pr-4">Customer</th>
                <th className="py-2 pr-4">Plan</th>
                <th className="py-2 pr-4">Status</th>
                <th className="py-2 pr-4">SSL</th>
                <th className="py-2 pr-4">Version</th>
                <th className="py-2 pr-4">Renews</th>
              </tr>
            </thead>
            <tbody>
              {instances.map((i) => (
                <tr key={i.id} className="border-b border-white/[0.04]">
                  <td className="py-2 pr-4">
                    <a href={i.url} target="_blank" rel="noopener noreferrer" className="text-brand-300 hover:underline">
                      {i.subdomain}
                    </a>
                  </td>
                  <td className="py-2 pr-4 text-slate-300">{i.userEmail}</td>
                  <td className="py-2 pr-4 text-slate-300">{i.planName}</td>
                  <td className="py-2 pr-4"><StatusDot status={i.status} /></td>
                  <td className="py-2 pr-4">{i.sslActive ? <Badge tone="green">on</Badge> : <span className="text-slate-500">—</span>}</td>
                  <td className="py-2 pr-4 text-slate-400">{i.version ?? "—"}</td>
                  <td className="py-2 pr-4 text-slate-400">{i.expiresAt ? i.expiresAt.slice(0, 10) : "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

