import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/lib/db";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import { FaqJsonLd } from "@/components/marketing/StructuredData";
import { IconDisk, IconShield, IconBolt, IconGlobe, IconApps, IconGauge, IconCheck } from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "NxCloud — Your Own Private Cloud, Fully Managed",
  description:
    "NxCloud is a managed Nextcloud on your own dedicated VM — Dropbox-style file sync, sharing and versioning, with your own subdomain, automatic HTTPS, and unlimited users. Your files, your box, we run it.",
  alternates: { canonical: "/nxcloud" },
  openGraph: {
    type: "article",
    title: "NxCloud — Your Own Private Cloud, Fully Managed",
    description:
      "A managed Nextcloud on your own VM. Sync every device, share files, own your data — no per-user SaaS tax.",
    url: `${APP_URL}/nxcloud`,
  },
};

const money = (c: number) => `$${(c / 100).toFixed(2)}`;
const storage = (gb: number) => (gb >= 1000 ? `${gb / 1000} TB` : `${gb} GB`);

const STEPS = [
  { n: "1", title: "Pick a plan", body: "Choose the storage you need. Every tier is a dedicated VM running managed Nextcloud, with unlimited users inside your instance." },
  { n: "2", title: "Choose your subdomain", body: "Your cloud goes live at yourname.nxcloud.nxeon.cloud with automatic HTTPS — no certificates to configure. A custom domain is coming soon." },
  { n: "3", title: "Sync everything", body: "Install the official desktop and mobile apps, sign in, and your files sync everywhere. Share links, versioning and trash are all built in." },
];

const NXCLOUD_FAQ = [
  { q: "What is NxCloud?", a: "A fully managed Nextcloud instance running on its own dedicated virtual machine. You get the complete Nextcloud experience — web file manager, desktop and mobile sync clients, share links, file versioning and trash — without installing, updating or maintaining anything. We run the server; you own the data." },
  { q: "How is this different from Dropbox or Google Drive?", a: "Your files live on your own isolated box, not in a shared multi-tenant service, and there's no per-user tax — every plan includes unlimited users within your instance. You get a private cloud with a custom subdomain instead of an account on someone else's platform." },
  { q: "Is my instance isolated from other customers?", a: "Yes. Each NxCloud is its own virtual machine with a hard kernel/VM boundary — not an account inside a shared app. Your data, your compute and your storage are yours alone." },
  { q: "Which devices can I sync?", a: "All of them. Nextcloud ships official clients for Windows, macOS, Linux, iOS and Android, plus a full web interface. Connect as many devices and users as you like." },
  { q: "Do I get automatic backups?", a: "Yes — VM snapshot backups are on by default so your data has a safety net. Higher tiers can also enable Nextcloud's own in-app backups." },
  { q: "Can I use my own domain?", a: "A free yourname.nxcloud.nxeon.cloud subdomain with automatic HTTPS is included today. Custom-domain support is on the near-term roadmap." },
];

export default async function NxcloudPage() {
  const plans = await db.nxCloudPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });

  return (
    <>
      <FaqJsonLd items={NXCLOUD_FAQ} />
      <PageHero
        eyebrow="NxCloud"
        title="Your own private cloud,"
        highlight="fully managed"
        sub="A managed Nextcloud on your own dedicated VM. Sync every device, share files, own your data — with your own subdomain, automatic HTTPS and unlimited users. No per-user SaaS tax."
        primary={{ label: "See plans", href: "#plans" }}
        secondary={{ label: "Open your dashboard", href: "/dashboard/nxcloud" }}
      />

      <Section>
        <SectionTitle title="Everything a private cloud needs, handled" sub="The full Nextcloud experience — none of the server maintenance." />
        <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          <FeatureCard icon={<IconDisk />} title="Sync every device">
            Official desktop (Windows, macOS, Linux) and mobile (iOS, Android) apps keep your files in sync everywhere — plus a full web file manager.
          </FeatureCard>
          <FeatureCard icon={<IconApps />} title="Share, version, restore" delay={0.05}>
            Password-protected share links with expiry, file versioning, and a trash bin to undelete — all built into Nextcloud, ready to use.
          </FeatureCard>
          <FeatureCard icon={<IconShield />} title="Isolated on your own VM" delay={0.1}>
            Every instance is its own virtual machine with a hard VM boundary — not an account in a shared app. Your data stays yours.
          </FeatureCard>
          <FeatureCard icon={<IconGlobe />} title="Your subdomain + auto HTTPS" delay={0.15}>
            Live at yourname.nxcloud.nxeon.cloud in minutes, with a certificate issued and renewed automatically. Nothing to configure.
          </FeatureCard>
          <FeatureCard icon={<IconBolt />} title="Unlimited users, no per-seat tax" delay={0.2}>
            Invite your whole family or team into your instance at no extra cost — you pay for the box, not per person.
          </FeatureCard>
          <FeatureCard icon={<IconGauge />} title="Managed + backed up" delay={0.25}>
            We run and patch the server, and VM snapshot backups are on by default so your only copy of your data is never your only copy.
          </FeatureCard>
        </div>
      </Section>

      <Section tone="panel">
        <SectionTitle title="Live in three steps" sub="No server admin, no command line — we stand it up for you." />
        <div className="mt-10 grid gap-5 lg:grid-cols-3">
          {STEPS.map((s, i) => (
            <Reveal key={s.n} delay={i * 0.05} className="relative rounded-2xl border border-white/[0.08] bg-navy-850/60 p-6">
              <span className="flex h-9 w-9 items-center justify-center rounded-full border border-brand-500/30 bg-brand-500/10 text-sm font-bold text-brand-200">{s.n}</span>
              <h3 className="mt-4 text-lg font-semibold text-white">{s.title}</h3>
              <p className="mt-1.5 text-sm leading-relaxed text-slate-400">{s.body}</p>
            </Reveal>
          ))}
        </div>
      </Section>

      <Section id="plans">
        <SectionTitle title="Simple monthly plans" sub="Own your box, own your data. Unlimited users on every tier. Cancel anytime." />
        {plans.length === 0 ? (
          <Reveal className="mt-8 text-center text-slate-400">Plans are coming soon — check back shortly.</Reveal>
        ) : (
          <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {plans.map((p, i) => (
              <Reveal
                key={p.id}
                delay={i * 0.05}
                className={`flex flex-col rounded-2xl border p-6 ${
                  p.featured ? "border-brand-500/50 bg-brand-500/[0.06]" : "border-white/[0.08] bg-navy-850/60"
                }`}
              >
                <div className="flex items-center justify-between">
                  <h3 className="text-lg font-semibold text-white">{p.name}</h3>
                  {p.featured && (
                    <span className="rounded-md bg-brand-500/15 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-brand-200">
                      Popular
                    </span>
                  )}
                </div>
                <p className="mt-2 text-3xl font-bold text-white">
                  {money(p.priceCents)}<span className="text-sm font-normal text-slate-400">/mo</span>
                </p>
                {p.tagline && <p className="mt-1 text-[11px] leading-snug text-slate-500">{p.tagline}</p>}
                <ul className="mt-4 flex-1 space-y-1.5 text-sm text-slate-300">
                  <li>{storage(p.storageGB)} storage</li>
                  <li>{p.ramMB / 1024} GB RAM · {p.vcpu} vCPU</li>
                  <li>{p.bandwidthTB} TB bandwidth</li>
                  <li>Unlimited users</li>
                  <li>Free subdomain + HTTPS</li>
                  {p.collabora && <li>Office suite (Collabora)</li>}
                  {p.talk && <li>Talk video &amp; chat</li>}
                </ul>
                <Link href="/dashboard/nxcloud" className="btn-primary mt-6 text-center">Get started</Link>
              </Reveal>
            ))}
          </div>
        )}
      </Section>

      <Section tone="panel">
        <SectionTitle eyebrow="FAQ" title="NxCloud questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {NXCLOUD_FAQ.map((f, i) => (
            <Reveal key={f.q} delay={i * 0.04}>
              <div className="rounded-2xl border border-white/[0.08] bg-navy-850/60 p-5">
                <h3 className="flex items-start gap-2 text-base font-semibold text-white">
                  <span className="mt-0.5 text-brand-300"><IconCheck size={16} /></span>
                  {f.q}
                </h3>
                <p className="mt-2 pl-6 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </Section>

      <Section>
        <CtaBand />
      </Section>
    </>
  );
}

