194	/**
195	 * Verify + reconcile every NxCloud instance:
196	 *  - PROVISIONING whose VM is RUNNING  → probe Nextcloud; ACTIVE once it serves.
197	 *    Past the grace window still not serving → ACTIVE with a caveat + admin alert
198	 *    (COMPLETED_WITH_ISSUES analog — never hang silently in PROVISIONING).
199	 *  - Mirror the backing Server's SUSPENDED / DELETING state onto the instance so
200	 *    the panel reflects a non-payment suspension enforced by the VPS billing sweep.
201	 *
202	 * Every row is individually try/caught so one bad instance can't abort the sweep.
203	 */
204	export async function nxcloudProvisionSweep(): Promise<void> {
205	  const active = await db.nxCloudInstance.findMany({
206	    where: { status: { in: ["PENDING", "PROVISIONING", "ACTIVE"] } },
207	    include: { server: true },
208	  });
209	
210	  for (const inst of active) {
211	    try {
212	      // Mirror a suspended backing VM onto the instance (non-payment enforced by
213	      // the VPS billing sweep) so the panel reflects it.
214	      if (inst.server && inst.status !== "SUSPENDED" && inst.server.status === "SUSPENDED") {
215	        await db.nxCloudInstance.update({ where: { id: inst.id }, data: { status: "SUSPENDED" } });
216	        continue;
217	      }
218	      // ACTIVE rows only needed the mirror check above. PENDING (e.g. the SANDBOX
219	      // provision path, which returns before the install hook runs) is treated the
220	      // same as PROVISIONING: verify serving, then promote.
221	      if (inst.status === "ACTIVE") continue;
222	
223	      // SANDBOX: no real VM/Nextcloud — simulate a completed install so the whole
224	      // order → provision → active flow is demoable end-to-end.
225	      if (SANDBOX) {
226	        await db.nxCloudInstance.update({
227	          where: { id: inst.id },
228	          data: { status: "ACTIVE", sslActive: true, version: "sandbox", provisionedAt: new Date(), error: null },
229	        });
230	        await notify(inst.userId, `Your NxCloud is ready`, `Your managed Nextcloud "${inst.subdomain}" is live (sandbox).`, `/dashboard/nxcloud`);
231	        continue;
232	      }
233	
234	      // The VM must be up before Nextcloud can be. Give the provisioner time.
235	      if (!inst.server || inst.server.status !== "RUNNING") continue;
236	
237	      const url = await nxcloudUrlFor(inst);
238	      const probe = await probeServing(url);
239	      if (probe.ok) {
240	        await db.nxCloudInstance.update({
241	          where: { id: inst.id },
242	          data: { status: "ACTIVE", sslActive: probe.https, version: probe.version, provisionedAt: new Date(), error: null },
243	        });
244	        await notify(inst.userId, `Your NxCloud is ready`, `Your managed Nextcloud is live at ${url}. Open it and sign in with the admin credentials in your panel.`, `/dashboard/nxcloud`);
245	        continue;
246	      }
247	
248	      // Not serving yet. Keep waiting until the grace window elapses; only then do
249	      // we stop claiming "setting up" and flip to ACTIVE-with-caveat + alert staff.
250	      const bootedAt = inst.server.updatedAt ?? inst.createdAt;
251	      const waitedMin = (Date.now() - new Date(bootedAt).getTime()) / 60000;
252	      if (waitedMin < INSTALL_GRACE_MIN) continue;
253	
254	      const note = `Nextcloud has not answered at ${url} after ${Math.round(waitedMin)} min. The VM is up; the install may still be finishing, or the ${await nxcloudZone()} DNS record for this instance may not point at the VM yet.`;
255	      await db.nxCloudInstance.update({
256	        where: { id: inst.id },
257	        data: { status: "ACTIVE", error: note, provisionedAt: new Date() },
258	      });
259	      await notify(
260	        inst.userId,
261	        `Your NxCloud is up — with caveats`,
262	        `We provisioned the VM but couldn't confirm Nextcloud is answering yet at ${url}. Give it a few more minutes; if it still doesn't load, open a ticket.`,
263	        `/dashboard/nxcloud`,
264	      );
